SELECT bs."in.state" AS state, bs."in.county_name" AS county_name, sum(1) AS metadata_rows_count, count(distinct(bs.bldg_id)) AS model_count, sum(bs.weight) AS units_count, sum(bs."out.electricity.total.energy_consumption" * bs.weight) AS "electricity.total.energy_consumption" FROM resstock_2024_amy2018_release_2_metadata AS bs WHERE bs.applicability = true AND bs.upgrade = 0 AND bs."in.state" IN ('CO', 'WY') AND bs.bldg_id IN (13, 16, 33, 128, 182, 196, 244, 245, 282, 565, 836, 1629, 2526, 3325, 3755, 4135) GROUP BY 1, 2 ORDER BY 1, 2